def get_mode(val_list):
    """Get the most common value in the list"""
    counts = {}
    for v in val_list:
        counts[v] = counts.get(v, 0) + 1
    return max(counts.items(), key=lambda x: x[1])[0]

def get_minority(val_list):
    """Get the values that appear less frequently"""
    counts = {}
    for v in val_list:
        counts[v] = counts.get(v, 0) + 1
    # Find values with count != most common count
    max_count = max(counts.values())
    return [v for v, c in counts.items() if c != max_count]

